cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled direct 3D convolution (kernel size kH x kW x kD, general stride/padding/dilation/groups).
// Designed for the case kD is small (here typically 1) so the "depth" dimension is handled by an
// extra grid dimension while (H, W) receive the tiled cooperative treatment.

template <typename T>
__global__ void conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win, int D,
    int Cout, int Cin_per_group, int Cout_per_group, int groups,
    int kH, int kW, int kD,
    int stride, int padding, int dilation,
    int Hout, int Wout, int Dout,
    int oc_per_block)
{
  constexpr int Threads = 128;
  constexpr int PVec    = 2;
  constexpr int MAX_OC  = 8;
  constexpr int KChunk  = 64;

  const int tid = threadIdx.x;

  const int n_od    = blockIdx.z;
  const int n       = n_od / Dout;
  const int od      = n_od % Dout;

  const int oc_base = blockIdx.y * oc_per_block;
  const int group   = oc_base / Cout_per_group;
  const int cin_start = group * Cin_per_group;

  const int P_total = Hout * Wout;
  const int PTile    = Threads * PVec;
  const int p_block  = blockIdx.x * PTile;

  // Strides (contiguous layouts)
  const int64_t sXn = (int64_t)Cin * H * Win * D;
  const int64_t sXc = (int64_t)H * Win * D;
  const int64_t sXh = (int64_t)Win * D;
  const int64_t sXw = (int64_t)D;

  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;

  const int64_t sWo  = (int64_t)Cin_per_group * kH * kW * kD;
  const int64_t sWc  = (int64_t)kH * kW * kD;
  const int64_t sWh  = (int64_t)kW * kD;
  const int64_t sWw  = (int64_t)kD;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win, D),
      make_stride(sXc, sXh, sXw, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout, Dout),
      make_stride(sYc, sYh, sYw, Int<1>{}));

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin_per_group, kH, kW, kD),
      make_stride(sWo, sWc, sWh, sWw, Int<1>{}));

  __shared__ T sW_raw[MAX_OC * KChunk];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<MAX_OC>{}, Int<KChunk>{}),
      make_stride(Int<KChunk>{}, Int<1>{}));

  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];
  int ih0_arr[PVec];
  int iw0_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i]  = oh;
      ow_arr[i]  = ow;
      ih0_arr[i] = oh * stride - padding;
      iw0_arr[i] = ow * stride - padding;
    } else {
      oh_arr[i] = 0; ow_arr[i] = 0; ih0_arr[i] = 0; iw0_arr[i] = 0;
    }
  }

  const int id_base = od * stride - padding;
  const int K_total = Cin_per_group * kH * kW * kD;

  float acc[MAX_OC][PVec];
  #pragma unroll
  for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
    int oc = oc_base + oc_l;
    float bval = 0.0f;
    if (oc_l < oc_per_block && oc < Cout && Bias != nullptr) {
      bval = (float)Bias[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[oc_l][i] = bval;
  }

  for (int k0 = 0; k0 < K_total; k0 += KChunk) {
    for (int kk = tid; kk < KChunk; kk += Threads) {
      int k_global = k0 + kk;
      #pragma unroll
      for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
        T wval = T(0);
        if (oc_l < oc_per_block) {
          int oc = oc_base + oc_l;
          if (oc < Cout && k_global < K_total) {
            int kd_i = k_global % kD;
            int t1   = k_global / kD;
            int kw_i = t1 % kW;
            int t2   = t1 / kW;
            int kh_i = t2 % kH;
            int cin_off = t2 / kH;
            wval = mW(oc, cin_off, kh_i, kw_i, kd_i);
          }
        }
        sW(oc_l, kk) = wval;
      }
    }
    __syncthreads();

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;

      int ih0 = ih0_arr[i];
      int iw0 = iw0_arr[i];

      for (int kk = 0; kk < KChunk; ++kk) {
        int k_global = k0 + kk;
        if (k_global >= K_total) break;

        int kd_i = k_global % kD;
        int t1   = k_global / kD;
        int kw_i = t1 % kW;
        int t2   = t1 / kW;
        int kh_i = t2 % kH;
        int cin_off = t2 / kH;

        int ih = ih0 + kh_i * dilation;
        if ((unsigned)ih >= (unsigned)H) continue;
        int iw = iw0 + kw_i * dilation;
        if ((unsigned)iw >= (unsigned)Win) continue;
        int id = id_base + kd_i * dilation;
        if ((unsigned)id >= (unsigned)D) continue;

        int cin = cin_start + cin_off;
        float xval = (float)mX(cin, ih, iw, id);

        #pragma unroll
        for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
          if (oc_l >= oc_per_block) break;
          float wval = (float)sW(oc_l, kk);
          acc[oc_l][i] += xval * wval;
        }
      }
    }
    __syncthreads();
  }

  #pragma unroll
  for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
    if (oc_l >= oc_per_block) break;
    int oc = oc_base + oc_l;
    if (oc >= Cout) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      int oh = oh_arr[i];
      int ow = ow_arr[i];
      mY(oc, oh, ow, od) = static_cast<T>(acc[oc_l][i]);
    }
  }
}

torch::Tensor conv3d_kh_kw_forward(torch::Tensor x,
                                    torch::Tensor w,
                                    c10::optional<torch::Tensor> b,
                                    int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, D]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin/groups, kH, kW, kD]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  int64_t D   = x.size(4);

  int64_t Cout = w.size(0);
  int64_t Cin_per_group = w.size(1);
  int64_t kH = w.size(2);
  int64_t kW = w.size(3);
  int64_t kD = w.size(4);

  TORCH_CHECK(Cin == Cin_per_group * groups, "Cin must equal Cin_per_group * groups");
  TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");
  int64_t Cout_per_group = Cout / groups;

  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - dilation * (kH - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (kW - 1) - 1) / stride + 1;
  int64_t Dout = (D + 2 * padding - dilation * (kD - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());

  constexpr int MAX_OC  = 8;
  constexpr int Threads = 128;
  constexpr int PVec    = 2;

  int oc_per_block = (int)std::min<int64_t>(Cout_per_group, MAX_OC);
  while (oc_per_block > 1 && (Cout_per_group % oc_per_block) != 0) oc_per_block--;

  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + oc_per_block - 1) / oc_per_block),
      (unsigned)(N * Dout)
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv3d_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win, (int)D,
      (int)Cout, (int)Cin_per_group, (int)Cout_per_group, (int)groups,
      (int)kH, (int)kW, (int)kD,
      (int)stride, (int)padding, (int)dilation,
      (int)Hout, (int)Wout, (int)Dout,
      oc_per_block
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_khkw1_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_kh_kw_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution with square (kH x kW) spatial kernel and kernel_size=1 along
    the last ("depth") axis, implemented with a single fused custom CUTE kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        # weight shape matches nn.Conv3d layout: [out_channels, in_channels/groups, kH, kW, kD=1]
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, 1)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * self.kernel_size * self.kernel_size * 1
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_kh_kw_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

