// Designed for the case kD is small (here typically 1) so the "depth" dimension is handled by an
// extra grid dimension while (H, W) receive the tiled cooperative treatment.

template <typename T>
__global__ void conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win, int D,
    int Cout, int Cin_per_group, int Cout_per_group, int groups,
    int kH, int kW, int kD,
    int stride, int padding, int dilation,
    int Hout, int Wout, int Dout,
    int oc_per_block)
{
  constexpr int Threads = 128;
  constexpr int PVec    = 2;
  constexpr int MAX_OC  = 8;
  constexpr int KChunk  = 64;

  const int tid = threadIdx.x;

  const int n_od    = blockIdx.z;
  const int n       = n_od / Dout;
  const int od      = n_od % Dout;

  const int oc_base = blockIdx.y * oc_per_block;
  const int group   = oc_base / Cout_per_group;
  const int cin_start = group * Cin_per_group;

  const int P_total = Hout * Wout;
  const int PTile    = Threads * PVec;
  const int p_block  = blockIdx.x * PTile;

  // Strides (contiguous layouts)
  const int64_t sXn = (int64_t)Cin * H * Win * D;
  const int64_t sXc = (int64_t)H * Win * D;
  const int64_t sXh = (int64_t)Win * D;
  const int64_t sXw = (int64_t)D;

  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;

  const int64_t sWo  = (int64_t)Cin_per_group * kH * kW * kD;
  const int64_t sWc  = (int64_t)kH * kW * kD;
  const int64_t sWh  = (int64_t)kW * kD;
  const int64_t sWw  = (int64_t)kD;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win, D),
      make_stride(sXc, sXh, sXw, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout, Dout),
      make_stride(sYc, sYh, sYw, Int<1>{}));

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin_per_group, kH, kW, kD),
      make_stride(sWo, sWc, sWh, sWw, Int<1>{}));

  __shared__ T sW_raw[MAX_OC * KChunk];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<MAX_OC>{}, Int<KChunk>{}),
      make_stride(Int<KChunk>{}, Int<1>{}));

  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];
  int ih0_arr[PVec];
  int iw0_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
