      ow_arr[i]  = ow;
      ih0_arr[i] = oh * stride - padding;
      iw0_arr[i] = ow * stride - padding;
    } else {
      oh_arr[i] = 0; ow_arr[i] = 0; ih0_arr[i] = 0; iw0_arr[i] = 0;
    }
  }

  const int id_base = od * stride - padding;
  const int K_total = Cin_per_group * kH * kW * kD;

  float acc[MAX_OC][PVec];
  #pragma unroll
  for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
    int oc = oc_base + oc_l;
    float bval = 0.0f;
    if (oc_l < oc_per_block && oc < Cout && Bias != nullptr) {
      bval = (float)Bias[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[oc_l][i] = bval;
  }

  for (int k0 = 0; k0 < K_total; k0 += KChunk) {
    for (int kk = tid; kk < KChunk; kk += Threads) {
      int k_global = k0 + kk;
      #pragma unroll
      for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
        T wval = T(0);
        if (oc_l < oc_per_block) {
          int oc = oc_base + oc_l;
