            int kd_i = k_global % kD;
            int t1   = k_global / kD;
            int kw_i = t1 % kW;
            int t2   = t1 / kW;
            int kh_i = t2 % kH;
            int cin_off = t2 / kH;
            wval = mW(oc, cin_off, kh_i, kw_i, kd_i);
