        float xval = (float)mX(cin, ih, iw, id);

        #pragma unroll
        for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
          if (oc_l >= oc_per_block) break;
          float wval = (float)sW(oc_l, kk);
          acc[oc_l][i] += xval * wval;
        }
      }
    }
    __syncthreads();
  }

  #pragma unroll
  for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
    if (oc_l >= oc_per_block) break;
    int oc = oc_base + oc_l;
    if (oc >= Cout) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
